successful_execution_receipts.command:
cd /app && python3 - <<'EOF'
p='vm/vmDefaultArgs_test.go'
s=open(p).read()
s=s.replace('''import (
	"fmt"
	"testing"
)
''','''import (
	"fmt"
	"testing"

	"github.com/mattn/anko/ast"
	"github.com/mattn/anko/ast/astutil"
	"github.com/mattn/anko/parser"
)
''')
s+='''
func TestDefaultArgumentsAST(t *testing.T) {
	t.Parallel()

	stmt, err := parser.ParseSrc(`func f(a = 1, b = 2) { return a + b }`)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	err = astutil.Walk(stmt, func(node interface{}) error {
		if fe, ok := node.(*ast.FuncExpr); ok {
			found = true
			if len(fe.Defaults) != 2 || fe.Defaults[0] == nil || fe.Defaults[1] == nil {
				t.Errorf("unexpected defaults: %#v", fe.Defaults)
			}
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if !found {
		t.Fatal("no FuncExpr found")
	}
}
'''
open(p,'w').write(s)
EOF
gofmt -w vm/vmDefaultArgs_test.go && go test -count=1 ./vm/ -run 'TestDefaultArguments' -v 2>&1 | tail -20
